import 'package:flutter/material.dart';
import '../services/auth_service.dart';
import '../utils/validators.dart';
class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState() => _RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen> { final form=GlobalKey<FormState>(); final name=TextEditingController(), email=TextEditingController(), password=TextEditingController(), confirm=TextEditingController(); bool busy=false;
  Future<void> register() async { if(!form.currentState!.validate()) return; setState(()=>busy=true); try { await AuthService().signUp(name.text.trim(),email.text.trim(),password.text); if(mounted) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Account created. Check your email if confirmation is enabled.'))); Navigator.pop(context); } } catch (_) { if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Unable to create account. Please try a different email.'))); } finally { if(mounted) setState(()=>busy=false); } }
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create iBantay account')),body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Padding(padding:const EdgeInsets.all(24),child:Form(key:form,child:Column(children:[TextFormField(controller:name,validator:(v)=>requiredText(v,field:'Full name'),decoration:const InputDecoration(labelText:'Full name')),TextFormField(controller:email,validator:emailValidator,decoration:const InputDecoration(labelText:'Email')),TextFormField(controller:password,obscureText:true,validator:passwordValidator,decoration:const InputDecoration(labelText:'Password')),TextFormField(controller:confirm,obscureText:true,validator:(v)=>v==password.text?null:'Passwords do not match.',decoration:const InputDecoration(labelText:'Confirm password')),const SizedBox(height:24),FilledButton(onPressed:busy?null:register,child:Text(busy?'Creating…':'REGISTER'))])))))); }
}
